			local args = {
				[1] = "CreateTextures",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal"
					}
				}
			}
	
			_(args)
		end
		function AddDecal(part,asset,side)
			local args = {
				[1] = "SyncTexture",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal",
						["Texture"] = "rbxassetid://".. asset
					}
				}
			}
			_(args)
		end
	
		local function particle()
			while true do
				task.wait()
	
				for _, player in ipairs(game.Players:GetPlayers()) do
					local char = player.Character
					local hum  = char and char:FindFirstChildOfClass("Humanoid")
					local hrp  = char and char:FindFirstChild("HumanoidRootPart")
					if not (hum and hum.Health > 0 and hrp) then
						continue 
					end
	
					local spawnCF = hrp.CFrame * CFrame.new(math.random(),-5,math.random())
					local neewCF = hrp.CFrame * CFrame.new(math.random(),-1,math.random())
	
	
	
	
					local direction = Vector3.new(
						math.random(-1, 1), 
						0, 
						math.random(-1, 1)
					).Unit * 0.1
	
	
					local changeDirectionChance = 0.3
					local moveBackwardChance = 0.2
	
					local part = remote:InvokeServer("CreatePart", "Normal", spawnCF, workspace)
					part.CanCollide = false
					SetCollision(part, false)
					wait(0.1)
	
	
					task.defer(function()
						task.defer(function()
							SetCollision(part, false)
						end)
						task.defer(function()
							Resize(part, Vector3.new(3, 3, 0.001), part.CFrame)
						end)
						task.defer(function()
							SetTrans(part, 1)
						end)
						task.defer(function()
							SpawnDecal(part, Enum.NormalId.Front)
						end)
						task.defer(function()
							MovePart(part, neewCF)
						end)
						task.defer(function()
							AddDecal(part, decal, Enum.NormalId.Front)
						end)
						task.defer(function()
							SpawnDecal(part, Enum.NormalId.Back)
						end)
						task.defer(function()
							AddDecal(part, decal, Enum.NormalId.Back)
						end)
						task.defer(function()
							SetName(part, "fucking fe bypass in this shit")
						end)
					end)
	
					task.defer(function()
						for i = 1, 90 do
							if not part then break end
	
							if math.random() < changeDirectionChance then
								direction = Vector3.new(
									math.random(-1, 1), 
									0, 
									math.random(-1, 1)
								).Unit * 0.2
	
								if math.random() < moveBackwardChance then
									direction = -direction
								end
							end
	
	
							local riseAmount = 0.4
							local movement = Vector3.new(direction.X, riseAmount, direction.Z)
	
							local newCF = part.CFrame + movement
							Resize(part, Vector3.new(3, 3, 0.001), newCF)
							wait() 
						end
						if part then
							wait(9)
							task.defer(function()
								delete(part)
							end)
						end
					end)
				end
			end
		end
	
		particle()
	
	end)
end;
