function C_7d()
local script = G2L["7d"];
	script.Parent.MouseButton1Click:Connect(function()
	
		local function findBuildingTools()
			local player = game:GetService("Players").LocalPlayer
	
			for _, item in ipairs(player.Character:GetChildren()) do
				if item:IsA("Tool") and item:FindFirstChild("SyncAPI") then
					return item
				end
			end
	
			for _, item in ipairs(player.Backpack:GetChildren()) do
				if item:IsA("Tool") and item:FindFirstChild("SyncAPI") then
					return item
				end
			end
	
			return nil
		end
	
		local buildingTools = findBuildingTools()
		if not buildingTools then
			warn("btools not found")
			return
		end
	
		local syncAPI        = buildingTools:FindFirstChild("SyncAPI")
		local serverEndpoint = syncAPI and syncAPI:FindFirstChild("ServerEndpoint")
	
		if not serverEndpoint then
			warn("btools not found")
			return
		end
	
		local disgusting = workspace:FindFirstChild("Sky") or workspace:FindFirstChild("sky") or workspace:FindFirstChild("B2S0NT0P!")
		if not disgusting then
			print"ok"
		end
	
		local args = {
			"Remove",                
			{ disgusting }           
		}
	
		local success, result
		if serverEndpoint:IsA("RemoteFunction") then
			success, result = pcall(function()
				return serverEndpoint:InvokeServer(unpack(args))
			end)
		else
	
			serverEndpoint:FireServer(unpack(args))
			success = true
		end
	
		if success then
	
			print"yay"
	
		end
	
		local gaysexgui = script.Parent.Parent
		local idtxt = gaysexgui:FindFirstChild("decalID")
		local decal = idtxt.Text
	
		local lnicky = game.Players.LocalPlayer
		local blue2spookyisbetterthayou = lnicky.Character or lnicky.CharacterAdded:Wait()
		local f3x
	
		for _, v in lnicky:GetDescendants() do
			if v.Name == "SyncAPI" then
				f3x = v.Parent
				break
			end
		end
	
		if not f3x then
			for _, v in game.ReplicatedStorage:GetDescendants() do
				if v.Name == "SyncAPI" then
					f3x = v.Parent
					break
				end
			end
		end
	
		if not f3x then
			warn("u dont have btools u skid")
			return
		end
	
		local trgrrg = f3x.SyncAPI.ServerEndpoint
	
		local function invokeServer(args)
			trgrrg:InvokeServer(unpack(args))
		end
	
		function CreatePart(cf, parent)
			local args = {
				"CreatePart",
				"Normal",
				cf,
				parent
			}
			invokeServer(args)
		end
	
		function SetName(part, name)
			local args = {
				"SetName",
				{part},
				name
			}
			invokeServer(args)
		end
	
		function AddMesh(part)
			local args = {
				"CreateMeshes",
				{
					{["Part"] = part}
				}
			}
			invokeServer(args)
		end
	
		function SetMesh(part, meshid)
			local args = {
				"SyncMesh",
				{
					{
						["Part"] = part,
						["MeshId"] = "rbxassetid://" .. meshid
					}
				}
			}
			invokeServer(args)
		end
	
		function MeshResize(part, size)
			local args = {
				"SyncMesh",
				{
					{
						["Part"] = part,
						["Scale"] = size
					}
				}
			}
			invokeServer(args)
		end
	
		function SetLocked(part, bool)
			local args = {
				"SetLocked",
				{part},
				bool
			}
			invokeServer(args)
		end
	
		function MovePart(part, cf)
			local args = {
				"SyncMove",
				{
					{
						["Part"] = part,
						["CFrame"] = cf
					}
				}
			}
			invokeServer(args)
		end
	
		function SetTexture(part, texid)
			local args = {
				"SyncMesh",
				{
					{
						["Part"] = part,
						["TextureId"] = "rbxassetid://" .. texid
					}
				}
			}
			invokeServer(args)
		end
	
		local pos = blue2spookyisbetterthayou.HumanoidRootPart.Position
		local part = CFrame.new(Vector3.new(math.floor(pos.X), math.floor(pos.Y) + 6, math.floor(pos.Z)))
	
		CreatePart(part, workspace)
	
		local skyboxinworkspace
		for _, v in workspace:GetChildren() do
			if v:IsA("BasePart") then
				local pos2 = v.Position
				if math.floor(pos2.X) == math.floor(pos.X) and math.floor(pos.Z) == math.floor(pos.Z) then
					skyboxinworkspace = v
					break
				end
			end
		end
	
		if not skyboxinworkspace then
			warn("no part in workspace")
			return
		end
	
		SetName(skyboxinworkspace, "Sky")
		AddMesh(skyboxinworkspace)
		SetMesh(skyboxinworkspace, "111891702759441")
		SetTexture(skyboxinworkspace, decal)
		MeshResize(skyboxinworkspace, Vector3.new(60000, 60000, 60000))
		SetLocked(skyboxinworkspace, true)
	
		local run = game:GetService("RunService")
		local rotatetypeshii = Vector3.new(math.random(), math.random(), math.random()).Unit
		local skypartrotation = 0
	
		run.Heartbeat:Connect(function(dt)
			skypartrotation = skypartrotation + dt * math.rad(55)
			local c00lframe = part * CFrame.fromAxisAngle(rotatetypeshii, skypartrotation)
			MovePart(skyboxinworkspace, c00lframe)
		end)
	end)
	
end;
