-- StarterGui.Blue2SpookyF3X.epic.Page3.ScrollingFrame.ActionButton.LocalScript
function C_112()
local script = G2L["112"];
	script.Parent.MouseButton1Click:Connect(function()
	
		local player = game.Players.LocalPlayer
		local char = player.Character
		local backpack = player.Backpack
	
		local function getf3x()
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			for _, v in ipairs(char:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
	
			return nil
		end
	
		-- get all info
	
		local f3x = getf3x()
		if not f3x then
			warn("you dont have f3x skid")
		end
		local syncapi = f3x.SyncAPI
		local serverendpoint = syncapi.ServerEndpoint
	
		local function setanchor(part, boolean)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end
	
		local function unanchorall()
			for _, v in ipairs(workspace:GetDescendants()) do
				if (v:IsA("BasePart") or v:IsA("UnionOperation"))
					and not table.find({"sky","Mesh","Sky","SkyBox","Skybox","skybox","B2S0NT0P!"}, v.Name) then
					spawn(function()
						setanchor(v, false)
					end)
				end
			end
		end
	
		unanchorall()
	
	end)
end;
task.spawn(C_112);
