function C_12b()
local script = G2L["12b"];
	script.Parent.MouseButton1Click:Connect(function()
		local Players = game:GetService("Players")
		local RunService = game:GetService("RunService")
		local player = Players.LocalPlayer
		local char = player.Character or player.CharacterAdded:Wait()
		local hrp = char:WaitForChild("HumanoidRootPart")
	
		local function getBTools()
			for _, container in {player.Character, player.Backpack} do
				if container then
					for _, tool in ipairs(container:GetChildren()) do
						if tool:IsA("Tool") and tool:FindFirstChild("SyncAPI") then
							return tool
						end
					end
				end
			end
			return nil
		end
	
		local tool = getBTools()
		if not tool then
			warn("get f3x u skid")
			return
		end
	
		local remote = tool.SyncAPI:FindFirstChild("ServerEndpoint")
		if not remote or not remote:IsA("RemoteFunction") then
			warn("GET EM REMOTE!")
			return
		end
	
		RunService.RenderStepped:Connect(function(dt)
			local anchoredParts = {}
			for _, part in ipairs(workspace:GetDescendants()) do
				if part:IsA("BasePart") and part.Anchored and part.Name ~= "Sky" and part.Name ~= "sky" and part.Name ~= "B2S0NT0P!" then
					table.insert(anchoredParts, part)
				end
			end
	
			for _, part in ipairs(anchoredParts) do
				local currentPos = part.Position
				local targetPos = hrp.Position
				local direction = (targetPos - currentPos)
				local moveVector = direction.Unit * math.min(direction.Magnitude, 40 * dt)
	
				local newCF = CFrame.new(currentPos + moveVector)
				local args = {
					"SyncMove",
					{
						{
							Part = part,
							CFrame = newCF
						}
					}
				}
				pcall(function()
					remote:InvokeServer(unpack(args))
				end)
			end
		end)
		
	   
	end)
end;
task.spawn(C_12b);
