function C_150()
local script = G2L["150"];
	script.Parent.MouseButton1Click:Connect(function()
		local player = game.Players.LocalPlayer
		local char = player.Character or player.CharacterAdded:Wait()
		local btool
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				btool = v.Parent
			end
		end
		for i,v in game.ReplicatedStorage:GetDescendants() do
			if v.Name == "SyncAPI" then
				btool = v.Parent
			end
		end
	
		if not btool then
			warn("get btools you skid")
			return
		end
	
		local rm = btool.SyncAPI.ServerEndpoint
	
		function _(args)
			pcall(function()
				rm:InvokeServer(unpack(args))
			end)
		end
	
		function SetLocked(part, boolean)
			local args = {
				[1] = "SetLocked",
				[2] = { [1] = part },
				[3] = boolean
			}
			_(args)
		end
	
		function AddMesh(part)
			local args = {
				[1] = "CreateMeshes",
				[2] = { [1] = { ["Part"] = part } }
			}
			_(args)
		end
	
		function MeshResize(part, size)
			local args = {
				[1] = "SyncMesh",
				[2] = { [1] = { ["Part"] = part, ["Scale"] = size } }
			}
			_(args)
		end
	
		function SetMeshType(part, mesh)
			local args = {
				[1] = "SyncMesh",
				[2] = { [1] = { ["Part"] = part, ["MeshType"] = mesh } }
			}
			_(args)
		end
	
		function Color(part, color)
			local args = {
				[1] = "SyncColor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Color"] = color,
						["UnionColoring"] = false
					}
				}
			}
			_(args)
		end
	
		function isSpecial(part)
			if part.Name ~= "Head" then return false end
			for _, mesh in ipairs(part:GetChildren()) do
				if mesh:IsA("SpecialMesh") then
					if mesh.MeshType == Enum.MeshType.Brick and
						mesh.Scale == Vector3.new(1.2, 2.1, 0.2) then
						return true
					end
				end
			end
			return false
		end
	
		function randomise()
			local plr = char or workspace:FindFirstChild(player.Name)
			if not plr then return end
	
			for _, v in plr:GetDescendants() do
				if v:IsA("BasePart") and not isSpecial(v) then
					task.spawn(function()
						SetLocked(v, false)
	
						local hasMesh = false
						for _, c in ipairs(v:GetChildren()) do
							if c:IsA("SpecialMesh") then
								hasMesh = true
								break
							end
						end
	
						if not hasMesh then
							AddMesh(v)
							task.wait(0.1)
						end
	
						local mshtypes = { "Sphere", "Cylinder", "Wedge", "Brick" }
						local random = mshtypes[math.random(1, #mshtypes)]
						SetMeshType(v, random)
	
						MeshResize(v, Vector3.new(
							math.random(1),
							math.random(1),
							math.random(1)
							))
	
						Color(v, Color3.fromRGB(
							math.random(0, 255),
							math.random(0, 255),
							math.random(0, 255)
							))
					end)
				end
			end
		end
	
		task.spawn(function()
			while true do
				randomise()
				task.wait(0.7)
			end
		end)
	
	end)
	
end;
