-- StarterGui.Blue2SpookyF3X.epic.Page4.ScrollingFrame.ActionButton.LocalScript
function C_168()
local script = G2L["168"];
	script.Parent.MouseButton1Click:Connect(function()
		local plr = game.Players.LocalPlayer
		local char = plr.Character 
	
		local function getF3X()
			for _, tool in ipairs(plr.Backpack:GetChildren()) do
				if tool:FindFirstChild("SyncAPI") then 
					return tool.SyncAPI.ServerEndpoint 
				end
			end
			for _, tool in ipairs(char:GetChildren()) do
				if tool:FindFirstChild("SyncAPI") then 
					return tool.SyncAPI.ServerEndpoint 
				end
			end
		end
	
		local endpoint = getF3X()
		if not endpoint then 
			warn("WHY U NO HAVE F3X") 
			return 
		end
	
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local player = game.Players.LocalPlayer
		local char = player.Character
		local tool
		u=game:GetService("UserInputService")
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
		for i,v in game.ReplicatedStorage:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	
		remote = tool.SyncAPI.ServerEndpoint
	
		function _(args)
			return remote:InvokeServer(unpack(args))
		end
	
		function CreatePart(cf,parent)
			local args = {
				[1] = "CreatePart",
				[2] = "Normal",
				[3] = cf,
				[4] = parent
			}
			return _(args)
		end
	
