		function trailconnect(obj, wat)
			local trail = {}
			for i = 1, 4 do 
				local p = Instance.new("Part") 
				p.BrickColor = obj.BrickColor
				p.formFactor = "Custom" 
				p.Size = Vector3.new(1,1,1)
				p.Locked = true 
				p.Anchored = true 
				p.CanCollide = false 
				local mesh = Instance.new("CylinderMesh", p) 
				mesh.Name = "Mesh" 
				table.insert(trail,{p,0}) 
			end
			local lastpos = obj.Position 
			local updatethis = 0 
			local dontdothis = false
			game:service'RunService'.Stepped:connect(function()
				if wat == true then if dontdothis then return end
					for i,v in pairs(trail) do
						game:service'Debris':AddItem(obj, 0)
						table.remove(v, i)
					end
					dontdothis = true
					return 
				end
				updatethis = ((updatethis) % 4) + 1
				local dstnc = (obj.Position - lastpos).magnitude 
				trail[updatethis][1].Mesh.Scale = Vector3.new(.2,dstnc,.2)
				trail[updatethis][1].Parent = obj.Parent
				trail[updatethis][1].CFrame = CFrame.new((obj.Position + lastpos)/2,obj.Position) * CFrame.Angles(math.pi/2, 0, 0)
				trail[updatethis][2] = 0 
				for i,v in pairs(trail) do 
					v[2] = v[2] + .15
					v[1].Transparency = v[2] 
				end 
				lastpos = obj.Position
			end)
		end 
	
		do --rayCast
			function rayCast(startpos, Speed, Gravity, Dmg, color)
				local ran,err = ypcall(function()
					local rayPart         = remote:InvokeServer("CreatePart","Normal",cf,workspace)
	
					spawn(function()
						SetCollision(rayPart, false)
					end)
	
					spawn(function()
						while task.wait() do
							MovePart(rayPart, rayPart.CFrame)
						end
					end)
	
					spawn(function()
						Resize(rayPart, Vector3.new(.2, 50, .2), rayPart.CFrame)
					end)
	
	
	
					spawn(function()
						Color(rayPart, Color3.fromRGB(math.random(0, 255), math.random(0, 255), math.random(0, 255)))
					end)   
	
	
					spawn(function()
						SetName(rayPart, "rayPart")
					end) 
	
	
					local hitobj = false
					local bulletposition = startpos.Position
					MovePart(rayPart, startpos.CFrame)
					trailconnect(rayPart, hitobj)
	
					local bulletvelocity = (Vector3.new(math.random(-2,2), math.random(-2,2), math.random(-2,2)))+( mouse.Hit.p - bulletposition).unit*Speed
					local bulletlastposition = bulletposition
	
					coroutine.resume(coroutine.create(function()
						while true do
	
							local dt = wait()
							bulletlastposition = bulletposition
							bulletvelocity = bulletvelocity + (Vector3.new(0, -3.81*Gravity, 0)*dt)
							bulletposition = bulletposition + (bulletvelocity*dt)
							local ray = Ray.new(bulletlastposition,  (bulletposition - bulletlastposition))
							local hit, hitposition = workspace:FindPartOnRayWithIgnoreList( ray, {char, workspace.dubstepbrooo, modelforparts} )
	
							if (torso.Position - rayPart.Position).magnitude > 840 then
								DestroyPart(rayPart)
								hitobj = true
								break
							end
	
	
							if hit then
								hitobj = true
								local damage = math.random(Dmg, Dmg+6)
								if hit.Parent:findFirstChild("Head") ~= nil then
									spawn(function()
										DestroyPart(hit.Parent.Head)
									end)
								elseif hit.Parent:IsA("Hat") and hit.Parent.Parent:findFirstChild("Humanoid") then
									spawn(function()
										DestroyPart(hit.Parent.Head)
									end)
								end
								local boom = remote:InvokeServer("CreatePart","Ball",cf,workspace)
								
								spawn(function()
									SetCollision(boom, false)
								end)
								
								spawn(function()
									Resize(boom, Vector3.new(10, 10, 10), boom.CFrame)
								end)
								
								spawn(function()
									MovePart(boom, CFrame.new(hitposition.x, hitposition.y, hitposition.z))
								end)
								
								spawn(function()
									Color(boom, Color3.fromRGB(math.random(0, 255), math.random(0, 255), math.random(0, 255)))
								end)
	
								spawn(function()
									SetCollision(boom, false)
								end)
								spawn(function()
									SetTrans(boom, 0.25)
								end)
								
	
	
	
								for i = 0, 20, 2.5 do
									Resize(boom, boom.Size + Vector3.new(i,i,i), boom.CFrame)
									SetTrans(boom, boom.Transparency + i/60)
									wait()
								end
								spawn(function()
									DestroyPart(boom)
								end)
								for _, v in pairs(workspace:GetDescendants()) do
									if v:IsA("Model") and v:FindFirstChild("Humanoid") then
										local head = v:FindFirstChild("Head")
										local torso = v:FindFirstChild("Torso")
										if head and torso then
											if (torso.Position - boom.Position).Magnitude < 16 and v ~= char then
												spawn(function()
													DestroyPart(v.Head)
												end)
											end
										end
									end
	
									if v and v:IsA("BasePart") and v.Name ~= "Base" and v.Name ~= "plzz" and v.Name ~= "dubstepbrooo" and v ~= char then
										if (v.Position - boom.Position).magnitude < 5 then
											spawn(function()
												SetAnchor(false, v)
											end)
										end
									end
								end
								
								for _, v in pairs(workspace:GetDescendants()) do
									if v and v:IsA("BasePart") 
										and v.Name ~= "Base" 
										and v.Name ~= "plzz" 
										and v.Name ~= "dubstepbrooo" 
										and v:IsDescendantOf(char) == false then 
										if (v.Position - boom.Position).magnitude < 5 then
											spawn(function()
												DestroyPart(v)
											end)
										end
									end
								end
	
								pcall(function()
									bulletposition = hitposition
									rayPart.CFrame = CFrame.new(bulletposition, bulletposition+bulletvelocity) * CFrame.Angles(math.pi/2, 0, 0)
									spawn(function()
										DestroyPart(rayPart)
									end)
								end)
								break
							end
							rayPart.CFrame = CFrame.new(bulletposition, bulletposition+bulletvelocity) * CFrame.Angles(math.pi/2, 0, 0)
							rayPart.Parent = modelforparts
						end
					end))
					for i = 70, 65, -1.5 do
						firing = true
						wait()
					end
					for i = 65, 70, 2.5 do
						firing = false
						wait()
					end
				end)
				if err then
					print(err)
				end
			end
		end
	
	
