							table.insert(b, v.Name)
						end
					end
				end
			end
	
	
			if #b > 0 then
				rq:InvokeServer(";speed " .. table.concat(b, ",") .. " 0")
			end
	
			a = CreatePart(char.HumanoidRootPart.CFrame + Vector3.new(0, -3.5, 0) , workspace, "Normal")
	
			task.defer(function()
