			end)
	
	
			task.defer(function()
				SetTexture(a, 132155326)
			end)
	
	
			task.defer(function()
				MeshColor(a, vector.create(5,5,5))
			end)
	
			wait(0.2)
			for i = 1, 12.5 do
				task.wait()
				MeshResize(a, a.Mesh.Scale + Vector3.new(10, 10, 10), CFrame.new())
			end
	
	
	
	
	
	
	
			f = CreatePart(char.HumanoidRootPart.CFrame + Vector3.new(0, 0, 0) , workspace, "Normal")
	
	
	
			task.defer(function()
				AddMesh(f)
			end)
	
			task.defer(function()
				SetMesh(f, 126088055641951)
			end)
	
	
			task.defer(function()
				SetTexture(f, 132155326)
			end)
	
	
			task.defer(function()
				MeshColor(f, vector.create(5,5,5))
			end)
	
			task.defer(function()
				MeshResize(f, Vector3.new(7000, 7000, 7000))
			end)
	
			task.defer(function()
				mat(f, Enum.Material.Glass)
			end)
	
			Resize(f, Vector3.new(7000,5,7000), char.HumanoidRootPart.CFrame + Vector3.new(0, 90000, 0))
	
			pooooos = a.CFrame
			n = CreatePart(pooooos , workspace, "Ball")
	
			Destroy(a)
	
			task.defer(function()
				Resize(n, Vector3.new(69,69,69), pooooos)
			end)
	
			task.defer(function()
				Color(n, Color3.new(1, 1, 1))
			end)
	
			task.defer(function()
				mat(n, Enum.Material.Neon)
			end)
	
			task.defer(function()
				SetCollision(n, false)
			end)
	
			task.delay(5, function()
				SetCollision(n, true)
			end)
	
	
			for _, v in pairs(plrz:GetPlayers()) do
				if v ~= plr then
					if (v.Character.HumanoidRootPart.Position - plr.Character.HumanoidRootPart.Position).Magnitude <= 100 then
						posy = v.Character.HumanoidRootPart.CFrame
						task.defer(function()
							modelmove(v.Character, v.Character.HumanoidRootPart.CFrame + Vector3.new(0, 90005, 0))
						end)
						task.delay(120, function()
							modelmove(v.Character, posy)
						end)
					end
				end
			end
	
			posy2 = char.HumanoidRootPart.CFrame
			char.HumanoidRootPart.CFrame = char.HumanoidRootPart.CFrame + Vector3.new(0, 90005, 0)
	
			task.delay(120, function()
				char.HumanoidRootPart.CFrame = posy2
			end)
	
	
			task.delay(120, function()
				Destroy(f)
				Destroy(n)
				rq:InvokeServer(";speed all 16")
			end)
	
			wait(0.1)
			for i = 1, 10 do
