		function Krab(id)
			e = char.HumanoidRootPart.CFrame.x
			f = char.HumanoidRootPart.CFrame.y
			g = char.HumanoidRootPart.CFrame.z
			CreatePart(CFrame.new(math.floor(e), math.floor(f), math.floor(g)) + Vector3.new(0, 53, 0), workspace)
	
			for i,v in game.Workspace:GetDescendants() do
				if v:IsA("BasePart") and v.CFrame.x == math.floor(e) and v.CFrame.z == math.floor(g) then
					--spawn(function()
					SetName(v,"pat")
					AddMesh(v)
					--end)
					--spawn(function()
					SetMesh(v,"455783801")
					SetTexture(v,id)
					--end)
					MeshResize(v,Vector3.new(0.7,0.7,0.7))
					SetLocked(v,true)
				end
			end
		end
		Krab("106211613892663")
	
		local function getPatPart()
			for _, v in workspace:GetDescendants() do
				if v:IsA("BasePart") and v.Name == "pat" then
					return v
				end
			end
			return nil
		end
	
		local pat = getPatPart()
		if pat then
			applyRedLight(pat)
		end
	
	
		RequestCommandSilent:InvokeServer(";music 7816195044 ;pitch 0.445 ;volume inf")
	
		wait(19)
		RequestCommandSilent:InvokeServer(";music 9046435309 ;volume inf")
	
		local function getTargetPart()
			for _, v in workspace:GetDescendants() do
				if v:IsA("BasePart") and v.Name == "pat" then
					return v
				end
			end
			return nil
		end
	
	
		local function getValidParts(targetPart)
			local parts = {}
	
			for _, v in workspace:GetDescendants() do
				if v:IsA("BasePart")
					and v:IsDescendantOf(workspace)
					and v ~= targetPart
					and v.Name ~= "Head"
					and v.Name ~= "Torso"
					and v.Name ~= "Baseplate"
					and v.Name ~= "SpawnLocation"
					and v.Size.X <= 60
					and v.Size.Z <= 60
				then
					table.insert(parts, v)
				end
			end
	
			return parts
		end
	
	
		local function movePartToward(part, targetCF)
			local dir = (targetCF.Position - part.Position).Unit
			local speed = 1
			local maxSpeed = 1000
			local acceleration = 4
	
			task.spawn(function()
				while speed < maxSpeed do
					speed += acceleration
					if speed > maxSpeed then speed = maxSpeed end
					task.wait(0.1)
				end
			end)
	
			local newCF = CFrame.new(part.Position + dir * speed)
			MovePart(part, newCF)
		end
	
		task.spawn(function()
			while true do
				local target = getTargetPart()
				if not target then task.wait(0.5) continue end
	
				local parts = getValidParts(target)
				if #parts == 0 then break end
	
				local index = 1
	
				while index <= #parts do
					for i = 1, 1 do
						local part = parts[index]
						index += 1
						if not part then break end
	
						task.spawn(function()
							while part and part:IsDescendantOf(workspace) do
								local distance = (part.Position - target.Position).Magnitude
	
								if part.Name == "HumanoidRootPart" and distance <= 14 then
									local parent = part.Parent
									if parent then
										delete(parent)
									end
									break
								elseif distance <= 10 then
									delete(part)
									break
								end
	
								SetAnchor(true, part)
								movePartToward(part, target.CFrame)
	
								task.wait(0.05)
							end
						end)
					end
					task.wait(0.3)
				end
	
				task.wait(1)
			end
		end)
		
	end)
end;
