function C_191()
local script = G2L["191"];
	script.Parent.MouseButton1Click:Connect(function() 
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local RequestCommandSilent = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent
	
		_G.disco = true
	
		while _G.disco == true do
			RequestCommandSilent:InvokeServer(";fogcolor 100000000000000000000000,0,0")
