			RequestCommandSilent:InvokeServer(";fogcolor 0,100000000000000000000000,0")
			wait(4)
			RequestCommandSilent:InvokeServer(";fogcolor 0,0,100000000000000000000000")
			wait(4)
		end
	
	end) 
end;
