					[1] = {
						["Part"] = part,
						["TextureId"] =	texture
					}
				}
			}
			_(args)
		end
		function Color(part,color)
			local args = {
				[1] = "SyncColor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Color"] = color,
						["UnionColoring"] = false
					}
				}
			}
			_(args)
		end
		function SetAnchor(boolean,part)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			_(args)
		end
		function DestroyPart(part)
			local args = {
				[1] = "Remove",
				[2] = {
					[1] = part
				}
			}
			_(args)
		end
	
		function SetAnchor(boolean,part)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			_(args)
		end
	
		function SetCollision(part,boolean)
			local args = {
				[1] = "SyncCollision",
				[2] = {
					[1] = {
						["Part"] = part,
						["CanCollide"] = boolean
					}
				}
			}
			_(args)
		end
	
		function AddMesh(part)
			local args = {
				[1] = "CreateMeshes",
				[2] = {
					[1] = {
						["Part"] = part
					}
				}
			}
			_(args)
		end
	
		function SetMesh(part,meshid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["MeshId"] = "rbxassetid://"..meshid
					}
				}
			}
			_(args)
		end
		function SpawnDecal(part,side)
			local args = {
				[1] = "CreateTextures",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal"
					}
				}
			}
	
			_(args)
		end
		function AddDecal(part,asset,side)
			local args = {
				[1] = "SyncTexture",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal",
						["Texture"] = "rbxasset://".. asset
					}
				}
			}
			_(args)
		end
		function MeshColor(part,color)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["VertexColor"] = color
					}
				}
			}
			_(args)
		end
		function MeshResize(part,size)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["Scale"] = size
					}
				}
			}
			_(args)
		end
		function Weld(part1,part2,lead)
			local args = {
				[1] = "CreateWelds",
				[2] = {
					[1] = part1,
					[2] = part2
				},
				[3] = lead
			}
			_(args)
		end
		function Jumpscare(player)
			if not player.Character:FindFirstChild("HumanoidRootPart") then
				wait()
				DestroyPart(player.Character.HumanoidRootPart)
				SetAnchor(true, player.Character.Head)
			end
			local part = serverendpoint:InvokeServer("CreatePart", "Normal", CFrame.new(Vector3.new(420, 5000, 6969)), player.Character)
			task.spawn(function()
				name(part, "HumanoidRootPart")
			end)
			task.spawn(function()
				lock(part, true)
			end)
			task.spawn(function()
				setcollision(part, false)
			end)
			task.spawn(function()
				SetTrans(part, 1)
			end)
	
			jump=serverendpoint:InvokeServer("CreatePart", "Normal", CFrame.new(Vector3.new(420, 5000, 6969)), workspace)
			task.spawn(function()
				AddMesh(jump)
			end)
			task.spawn(function()
				name(jump, "LOLNO")
			end)
			task.spawn(function()
				SetMesh(jump,"111891702759441")
			end)
			task.spawn(function()
				MeshResize(jump, Vector3.new(300,200,300))
			end)
			task.spawn(function()
				texture(jump,"rbxassetid://119163250541367")
			end)
			task.spawn(function()
				MeshColor(jump,vector.create(2,2,2))
			end)
			task.spawn(function()
				sound(80776947525537, jump)
			end)
	
			task.spawn(function()
				wait(9.3)
				RequestCommand:InvokeServer(";res " .. player.Name)
			end)
			wait(9.3)
			spawn(function()
				DestroyPart(jump)
			end)
		end
	
		game.Players.PlayerAdded:connect(function(plr)
			local frt = true
			plr.CharacterAdded:connect(function(character)
				if frt then
					task.spawn(function()
						Jumpscare(plr)
					end)
					frt = false
				end
			end)
		end)
	
		
	end)
end;
