					sync:InvokeServer("SyncSurface", {
						{ Part = created, Surfaces = {Top = ref.TopSurface, Front = ref.FrontSurface, Bottom = ref.BottomSurface, Right = ref.RightSurface, Left = ref.LeftSurface, Back = ref.BackSurface}}
					})
	
