							{ Part = created, Face = decal.Face, TextureType = "Decal" }
						})
						sync:InvokeServer("SyncTexture", {
							{ Part = created, Face = decal.Face, TextureType = "Decal", Texture = decal.Texture, Transparency = decal.Transparency }
