function C_1b4()
local script = G2L["1b4"];
	script.Parent.MouseButton1Click:Connect(function()
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local RequestCommand = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent
		local player = game.Players.LocalPlayer
		local char = player.Character
		local backpack = player.Backpack
	
		local Players = game:GetService("Players")
		local player = Players.LocalPlayer
	
		local character = player.Character or player.CharacterAdded:Wait()
	
		local storedCharacter = character
		local originalParent = storedCharacter.Parent
	
		storedCharacter.Parent = nil
	
		local player = game.Players.LocalPlayer
		local char = player.Character
		local backpack = player.Backpack
	
		local function getf3x()
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			for _, v in ipairs(char:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
	
			return nil
		end
	
		-- get all info
	
		local f3x = getf3x()
		if not f3x then
			warn("you dont have f3x skid")
		end
		local syncapi = f3x.SyncAPI
		local serverendpoint = syncapi.ServerEndpoint
	
		local function delete(part)
			local args = {
				[1] = "Remove",
				[2] = {
					[1] = part
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end
	
		local function deleteall()
			for _, v in ipairs(workspace:GetDescendants()) do
				if (v:IsA("BasePart") or v:IsA("UnionOperation")) and v.Name ~= "Sky" then
					spawn(function()
						delete(v)
					end)
				end
			end
		end
	
		deleteall()
	
		local function getf3x()
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			for _, v in ipairs(char:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			return nil
		end
	
		local f3x = getf3x()
		if not f3x then
			warn("you dont have f3x skid")
		end
		local syncapi = f3x.SyncAPI
		local serverendpoint = syncapi.ServerEndpoint
	
		function _(args)
			serverendpoint:InvokeServer(unpack(args))
		end
	
		local function addlight(part, brightness)
			local args = {
				[1] = "CreateLights",
				[2] = {
					[1] = {
						["Part"] = part,
						["LightType"] = "PointLight"
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end
	
		local function synclight(part, brightness)
			local args = {
				[1] = "SyncLighting",
				[2] = {
					[1] = {
						["Part"] = part,
						["LightType"] = "PointLight",
						["Range"] = 60,
						["Color"] = Color3.new(1, 0, 0)
					}
				}
			}
			serverendpoint:InvokeServer(unpack(args))
		end
	
		local function fire(part) 
	
			local argsCreate = {
				[1] = "CreateDecorations",
				[2] = {
					[1] = {
						["Part"] = part,
						["DecorationType"] = "Fire"
					}
				}
			}
	
	
			local argsSync = {
				[1] = "SyncDecorate",
				[2] = {
					[1] = {
						["Part"] = part,
						["DecorationType"] = "Fire",
						["Size"] = 30,
						["Heat"] = 9,
						["Color"] = Color3.fromRGB(255, 0, 0), 
						["SecondaryColor"] = Color3.fromRGB(255, 0, 0) 
					} 
				} 
			}
	
	
			_(argsCreate)
			_(argsSync)
		end
		function MovePart(part, cf)
			local args = {
				"SyncMove",
				{
					{
						Part = part,
						CFrame = cf
					}
				}
			}
			_(args)
		end
	
		local function resize(part, size, cf)
			local args = {
				"SyncResize",
				{
					{
						Part = part,
						CFrame = cf,
						Size = size
					}
				}
			}
			_(args)
		end
	
		function SetTrans(part,int)
			local args = {
				[1] = "SyncMaterial",
				[2] = {
					[1] = {
						["Part"] = part,
						["Transparency"] = int
					}
				}
			}
			_(args)
		end
	
		local function mat(part, mate)
			local args = {
				"SyncMaterial",
				{
					{
						Part = part,
						Material = mate
					}
				}
			}
			_(args)
		end
	
		local function transparency(part, trans)
			local args = {
				"SyncMaterial",
				{
					{
						Part = part,
						Transparency = trans
					}
				}
			}
			_(args)
		end
	
		local function color(part, color)
			local args = {
				"SyncColor",
				{
					{
						Part = part,
						Color = color,
						UnionColoring = false
					}
				}
			}
			_(args)
		end
	
		local function syncmeshid(part, id)
			local args = {
				"SyncMesh",
				{
					{
						Part = part,
						MeshId = "rbxassetid://" .. id
					}
				}
			}
			_(args)
		end
	
		local function makemesh(part)
			local args = {
				"CreateMeshes",
				{
					{
						Part = part
					}
				}
			}
			_(args)
		end
	
		local function syncmeshsize(part, vectora)
			local args = {
				"SyncMesh",
				{
					{
						Part = part,
						Scale = vectora
					}
				}
			}
			_(args)
		end
	
		local function syncmeshtexture(part, id)
			local args = {
				"SyncMesh",
				{
					{
						Part = part,
						TextureId = "rbxassetid://" .. id
					}
				}
			}
			_(args)
		end
	
		local function name(part, stringa)
			local args = {
				"SetName",
				{ part },
				stringa
			}
			_(args)
		end
	
		local function lock(part, boolean)
			local args = {
				"SetLocked",
				{ part },
				boolean
			}
			_(args)
		end
	
	
	
		local function setcollision(part, booleana)
			local args = {
				"SyncCollision",
				{
					{
						Part = part,
						CanCollide = booleana
					}
				}
			}
			_(args)
		end
	
		local function setanchor(part, boolean)
			local args = {
				"SyncAnchor",
				{
					{
						Part = part,
						Anchored = boolean
					}
				}
			}
			_(args)
		end
	
		local function createdecal(part, side)
			local args = {
				"CreateTextures",
				{
					{
						Part = part,
						Face = side,
						TextureType = "Decal"
					}
				}
			}
			_(args)
		end
	
		local function setdecal(part, asset, side)
			local args = {
				"SyncTexture",
				{
					{
						Part = part,
						Face = side,
						TextureType = "Decal",
						Texture = "rbxassetid://" .. asset
					}
				}
			}
			_(args)
		end
	
		function toptexturecreate(part)
			local args = {
				[1] = "CreateTextures",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = Enum.NormalId.Top,
						["TextureType"] = "Texture"
					}
				}
			}
	
			_(args)
		end
		function toptextureadd(part)
			local args = {
				[1] = "SyncTexture",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = Enum.NormalId.Top,
						["TextureType"] = "Texture",
						["Texture"] = "rbxassetid://13199422086",
						["StudsPerTileV"] = 2,
						["StudsPerTileU"] = 2
					}
				}
			}
			_(args)
		end
	
		local function RealmV2()
			local position = CFrame.new(0, 0, 0)
			local base = serverendpoint:InvokeServer("CreatePart", "Normal", position, workspace)
			resize(base, Vector3.new(1000, 1, 1000), position)
			toptexturecreate(base)
			toptextureadd(base)
			color(base, Color3.fromRGB(0, 150, 0))
	
		end
		local function unanchorall()
			for _, v in ipairs(workspace:GetDescendants()) do
				if v:IsA("BasePart") or v:IsA("UnionOperation") then
					spawn(function()
						lock(v, false)
						setanchor(false, v)
					end)
				end
			end
		end
	
		local function realm()
			unanchorall()
			RealmV2()
		end
		realm()
		wait(1)
		storedCharacter.Parent = game.workspace
	end)
end;
