						})
						sync:InvokeServer("SyncLighting", {
							{ Part = created, LightType = "PointLight", Color = light2.Color, Range = light2.Range, Shadows = light2.Shadows }
						})
	
					end
				end)
			end
		end
	
		for _, part in next, imported_model:GetDescendants() do
