		remote = tool.SyncAPI.ServerEndpoint
	
		function _(args)
			return remote:InvokeServer(unpack(args))
		end
	
		function CreatePart(cf,parent)
			local args = {
				[1] = "CreatePart",
				[2] = "Normal",
				[3] = cf,
				[4] = parent
			}
			return _(args)
		end
	
		function SetName(part, stringg)
			local args = {
				[1] = "SetName",
				[2] = {
					[1] = part
				},
