						["Anchored"] = boolean
					}
				}
			}
			_(args)
		end
		function DestroyPart(part)
			local args = {
				[1] = "Remove",
				[2] = {
					[1] = part
				}
			}
			_(args)
		end
	
		function SetAnchor(boolean,part)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			_(args)
		end
	
		function SetCollision(part,boolean)
			local args = {
				[1] = "SyncCollision",
				[2] = {
					[1] = {
						["Part"] = part,
						["CanCollide"] = boolean
					}
				}
			}
			_(args)
		end
	
		function AddMesh(part)
			local args = {
				[1] = "CreateMeshes",
				[2] = {
					[1] = {
						["Part"] = part
					}
				}
			}
			_(args)
		end
	
		function SetMesh(part,meshid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["MeshId"] = "rbxassetid://"..meshid
					}
				}
			}
			_(args)
		end
		function SpawnDecal(part,side)
			local args = {
				[1] = "CreateTextures",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal"
					}
				}
			}
	
			_(args)
		end
		function AddDecal(part,asset,side)
			local args = {
				[1] = "SyncTexture",
				[2] = {
					[1] = {
						["Part"] = part,
						["Face"] = side,
						["TextureType"] = "Decal",
						["Texture"] = "rbxasset://".. asset
					}
				}
			}
			_(args)
		end
		function MeshResize(part,size)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["Scale"] = size
					}
				}
			}
			_(args)
		end
		function Weld(part1,part2,lead)
			local args = {
				[1] = "CreateWelds",
				[2] = {
					[1] = part1,
					[2] = part2
				},
				[3] = lead
			}
			_(args)
		end
	
	
		function modelmove(model, seeframe)
			if not model or not model.Parent then return end
			local primary = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
			if not primary then return end
	
			local offsets = {}
			for _, obj in ipairs(model:GetDescendants()) do
				if obj:IsA("BasePart") then
					offsets[obj] = primary.CFrame:ToObjectSpace(obj.CFrame)
				end
			end
	
			local moveArgs = {
				[1] = "SyncMove",
				[2] = {}
			}
			for part, offset in pairs(offsets) do
				table.insert(moveArgs[2], {
					["Part"] = part,
					["CFrame"] = seeframe * offset
				})
			end
	
			_(moveArgs)
		end
	
	
		local u = game.Players.LocalPlayer.Character and game.Players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
		local targetModel = workspace[NAME]
	
		local seeframe = u.CFrame * CFrame.new(0, 0, -2)
		modelmove(targetModel, seeframe)
	
	
	
	
	end)
end;
