			local argsCreate = {
				[1] = "CreateDecorations",
				[2] = {
					[1] = {
						["Part"] = part,
						["DecorationType"] = "Smoke"
					}
				}
			}
	
	
			local argsSync = {
				[1] = "SyncDecorate",
				[2] = {
					[1] = {
						["Part"] = part,
						["DecorationType"] = "Smoke",
						["Size"] = size,
						["Color"] = color,
					} 
				} 
			}
	
	
			_(argsCreate)
			_(argsSync)
		end
		function SetMesh(part,meshid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["MeshId"] = "rbxassetid://"..meshid
					}
				}
			}
			_(args)
		end
		function SetTexture(part, texid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["TextureId"] = "rbxassetid://"..texid
					}
				}
			}
			_(args)
		end
		function SetName(part, stringg)
			local args = {
				[1] = "SetName",
				[2] = {
					[1] = workspace.Part
				},
				[3] = stringg
			}
	
			_(args)
		end
		function MeshResize(part,size)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					[1] = {
						["Part"] = part,
						["Scale"] = size
					}
				}
			}
			_(args)
		end
		function Weld(part1, part2,lead)
			local args = {
				[1] = "CreateWelds",
				[2] = {
					[1] = part1,
					[2] = part2
				},
				[3] = lead
			}
			_(args)
	
		end
		function SetLocked(part,boolean)
			local args = {
				[1] = "SetLocked",
				[2] = {
					[1] = part
				},
				[3] = boolean
			}
			_(args)
		end
		function SetTrans(part,int)
			local args = {
				[1] = "SyncMaterial",
				[2] = {
					[1] = {
						["Part"] = part,
						["Transparency"] = int
					}
				}
			}
			_(args)
		end
		function CreateSpotlight(part)
			local args = {
				[1] = "CreateLights",
				[2] = {
					[1] = {
						["Part"] = part,
						["LightType"] = "SpotLight"
					}
				}
			}
			_(args)
		end
		function SyncLighting(part,brightness)
			local args = {
				[1] = "SyncLighting",
				[2] = {
					[1] = {
						["Part"] = part,
						["LightType"] = "SpotLight",
						["Brightness"] = brightness
					}
				}
			}
			_(args)
		end
	
	
		local torso = workspace[NAME].Torso
		spawn(function()
			SetLocked(torso, false)
		end)
		spawn(function()
			AddMesh(torso)
		end)
		spawn(function()
			CreateSpotlight(torso)
		end)
		spawn(function()
			SyncLighting(torso,30)
		end)
		spawn(function()
			MeshResize(torso,Vector3.new(2, 2, 1.5))
		end)
		spawn(function()
			SetMesh(torso, "2231280549")
		end)
		spawn(function()
			SetTrans(torso, 0)
		end)
		spawn(function()
			SetTexture(torso, "2231280614")
		end)
	
		local t = torso.CFrame + Vector3.new(-3, 4, 0)
		smoke = remote:InvokeServer("CreatePart", "Normal", t, torso)
	
		spawn(function()
			SetTrans(smoke, 1)
		end)
		spawn(function()
			Weld(smoke, torso, torso)
		end)
		spawn(function()
			addSmoke(smoke, Color3.fromRGB(30, 30, 30), 5)
		end)
		spawn(function()
			SetAnchor(false, smoke)
		end)
		spawn(function()
			SetCollision(smoke, false)
		end)
	
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local RequestCommandSilent = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent
	
		RequestCommandSilent:InvokeServer(";speed " .. NAME .. " 50")
	
		function KillTarget(target)
			local head = target.Character.Head
			DestroyPart(head)
		end
	
	
		local Players = game:GetService("Players")
	
		while true do
			task.wait(0.1)
			for _, part in ipairs(workspace[NAME]:GetDescendants()) do
				if part:IsA("BasePart") and part.Name == "Torso" then
					for _, plr in ipairs(Players:GetPlayers()) do
						if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") and plr.Name ~= NAME then
							local dist = (plr.Character.HumanoidRootPart.Position - part.Position).Magnitude
							if dist < 3 then
								KillTarget(plr)
							end
						end
					end
				end
			end
		end
	
	
	
	
	end)
end;
task.spawn(C_1e1);
