					[1] = part1,
					[2] = part2
				},
				[3] = lead
			}
			_(args)
		end
	
	
		function modelmove(model, seeframe)
			if not model or not model.Parent then return end
			local primary = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
			if not primary then return end
	
			local offsets = {}
			for _, obj in ipairs(model:GetDescendants()) do
				if obj:IsA("BasePart") then
					offsets[obj] = primary.CFrame:ToObjectSpace(obj.CFrame)
				end
			end
	
			local moveArgs = {
				[1] = "SyncMove",
				[2] = {}
			}
			for part, offset in pairs(offsets) do
				table.insert(moveArgs[2], {
					["Part"] = part,
					["CFrame"] = seeframe * offset
				})
			end
	
			_(moveArgs)
		end
	
	
		local targ = workspace[NAME]
	
		task.spawn(function()
			local angle = 0
			while true do
				angle += math.rad(0.11)
				local speen = targ.PrimaryPart.CFrame * CFrame.Angles(0.13, angle, angle)
				modelmove(targ, speen)
				task.wait()
			end
		end)
	
	
	
	
	task.spawn(function()
		local angle = 1
		while true do
			angle += math.rad(1)
			local speen = targ.PrimaryPart.CFrame * CFrame.Angles(1, 0, 0)
			modelmove(targ, speen)
			task.wait(0.2)
		end
	end)
	end)
	
	
	
end;
