				end)
				spawn(function()
					Color(p2, Color3.fromRGB(0, 0, 0))
				end)
				spawn(function()
					SetTrans(p2, 0.3)
				end)
				spawn(function()
					mat(p2, Enum.Material.Neon)
				end)
				wait(0.5)
				DestroyPart(p2)
			end)
			wait(0.0005)
		end
	
	end)
	
	
end;
