function C_1f9()
local script = G2L["1f9"];
	script.Parent.MouseButton1Click:Connect(function()
		local NAME = script.Parent.Parent.Parent.TextBox.Text -- name of le target
	
		local player = game.Players.LocalPlayer
		local char = player.Character
		local backpack = player.Backpack
	
		-- find F3X tool
		local function getf3x()
			for _, v in ipairs(backpack:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			for _, v in ipairs(char:GetChildren()) do
				if v:FindFirstChild("SyncAPI") then
					return v
				end
			end
			return nil
		end
	
		local f3x = getf3x()
		if not f3x then
			warn("You don't have F3X equipped.")
			return
		end
	
		local serverendpoint = f3x.SyncAPI.ServerEndpoint
	
		-- helpers
		local function _(args)
			return serverendpoint:InvokeServer(unpack(args))
		end
	
		local function CreatePart(cf, parent)
			local args = {
				[1] = "CreatePart",
				[2] = "Normal",
				[3] = cf,
				[4] = parent
			}
			return _(args)
		end
	
		local function SetName(part, stringg)
			local args = {
				[1] = "SetName",
				[2] = {
					[1] = part
				},
				[3] = stringg
			}
			_(args)
		end
	
		local function MovePart(part, cf)
			local args = {
				[1] = "SyncMove",
				[2] = {
					[1] = {
						["Part"] = part,
						["CFrame"] = cf
					}
				}
			}
			_(args)
		end
	
		local function SetTrans(part, int)
			local args = {
				[1] = "SyncMaterial",
				[2] = {
					[1] = {
						["Part"] = part,
						["Transparency"] = int
					}
				}
			}
			_(args)
		end
	
		local function SetCollision(part, boolean)
			local args = {
				[1] = "SyncCollision",
				[2] = {
					[1] = {
						["Part"] = part,
						["CanCollide"] = boolean
					}
				}
			}
			_(args)
		end
	
		local function SetAnchor(boolean, part)
			local args = {
				[1] = "SyncAnchor",
				[2] = {
					[1] = {
						["Part"] = part,
						["Anchored"] = boolean
					}
				}
			}
			_(args)
		end
	
		local function DestroyPart(part)
			local args = {
				[1] = "Remove",
				[2] = {
					[1] = part
				}
			}
			_(args)
		end
	
	
		local targetPlayer = workspace[NAME]
	
	
		local hrp = targetPlayer.HumanoidRootPart
		local torso = targetPlayer:FindFirstChild("Torso") or targetPlayer:FindFirstChild("UpperTorso")
	
	
		local balls = CreatePart(CFrame.new(0, 0, 0), targetPlayer)
	
		SetName(balls, "HumanoidRootPart")
		SetCollision(balls, false)
		SetAnchor(true, balls)
		SetTrans(balls, 1)
	
	
		DestroyPart(hrp)
	
		for _, z in ipairs(workspace[NAME]:GetDescendants()) do
			if z:IsA("BasePart") then
				spawn(function()
					SetCollision(z, true)
				end)
			end
		end
	
		spawn(function()
			while task.wait() do
				local pos = torso.Position + Vector3.new(0, 2, 0) 
				MovePart(balls, CFrame.new(pos))
			end
		end)
	
	end)
	
	
end;
