function C_1ff()
local script = G2L["1ff"];
	script.Parent.MouseButton1Click:Connect(function()
	script.Parent.Parent.Parent.TextBox.Text = script.Parent.Text
	end)
end;
task.spawn(C_1ff);
-- StarterGui.Blue2SpookyF3X.StigmaWatermark.LocalScript
function C_202()
local script = G2L["202"];
	-- Stigma Ultimate logo (blue2spookyified 🤑)
	local TweenService = game:GetService("TweenService")
	
	local gui = script.Parent
	
	
	local ball = gui:FindFirstChild("spook")
	
	
	local Ring = ball:FindFirstChild("Spinny")
	
	local orbit = Ring:FindFirstChild("Orbit")
	
	
	for _, obj in pairs({ball, Ring, orbit}) do
		obj.ImageTransparency = 1
		TweenService:Create(obj, TweenInfo.new(1), {ImageTransparency = 0}):Play()
	end
	
	local ROTATION_MULTIPLIER = 60
	local rotationSpeed = 1.2
	
	task.spawn(function()
		local lastTime = tick()
		while true do
			local deltaTime = tick() - lastTime
			lastTime = tick()
	
			Ring.Rotation = Ring.Rotation + rotationSpeed * deltaTime * ROTATION_MULTIPLIER
			orbit.Rotation = orbit.Rotation - rotationSpeed * deltaTime * ROTATION_MULTIPLIER
	
			task.wait()
		end
	end)
	
	ball:TweenPosition(UDim2.new(0.458, 0, 0.408, 0), "Out", "Linear", 0.4, false)
	task.wait(4)
	ball:TweenPosition(UDim2.new(0, 11, 0.78, 0), "Out", "Sine", 0.7, false)
	
	local button = ball:FindFirstChild("TextButton")
	
	
	button.MouseButton1Click:Connect(function()
		local guiToggle = game.Players.LocalPlayer.PlayerGui:FindFirstChild("Blue2SpookyF3X")
			or game.CoreGui:FindFirstChild("Blue2SpookyF3X")
	
		if guiToggle then
			guiToggle.Enabled = not guiToggle.Enabled
		end
	end)
end;
task.spawn(C_202);

return G2L["1"]
